// The C++ side of the fp mul / sqr kernels on x86-64:
// - sbn3f_full, the out-of-line full product of src/fp/x86_64/mul.S (generated by
//   tools/generate_fp_mul.py): two windows of at most 234 limbs, the scratch on the stack
//   (u52::scratch_bytes(234, 234) + 64 at most). The u52 high product is called from the assembly
//   directly (sbn3i_mulhigh_u52, its scratch below the frame).
// - mul_m / sqr_m, the M entries (caller's Frame), meant for windows beyond the S entry's 234 limbs:
//   the high-product shape by a short product (short_high) of the top k+1 limbs, the full shape by
//   the full product of the windows written to z as it is.
#include "fp/kernel.hpp"
#include "backend/u52/kernels.hpp"
#include "core/x86_64/word.hpp"
#include "runtime/scratch.hpp"

using sbn::v3::fp::limb;
namespace u52 = sbn::v3::u52;

// z[0..an + bn) = a * b (a == b and an == bn: a square), the integer layer's scalar / u52 crossovers
// (src/product/api.cpp, 2026-10-09); f: the Frame for the u52 products, or none (stack)
static void full_product(limb *z, const limb *a, int64_t an, const limb *b, int64_t bn, sbn::v3::Frame *f) noexcept {
    const int64_t lo = an < bn ? an : bn, hi = an < bn ? bn : an;
    const bool square = a == b && an == bn;
    const bool scalar = square ? hi <= 14
                               : lo <= 1 || hi <= 8 || (hi <= 16 && lo * hi <= 100) || (lo == 2 && hi < 56) ||
                                     (lo == 3 && hi <= 28) || (lo == 4 && hi < 20);
    if (scalar) {
        if (square) sbn::v3::sqr_basecase_assumed(z, a, size_t(an));
        else sbn::v3::mul_basecase_assumed(z, a, size_t(an), b, size_t(bn));
        return;
    }
    if (f) {
        u52::multiply(z, a, size_t(an), b, size_t(bn), *f);
        return;
    }
    const size_t bytes = u52::scratch_bytes(size_t(an), size_t(bn)) + 64;
    void *buf = __builtin_alloca_with_align(bytes, 512);
    sbn::v3::Frame g = sbn::v3::Frame::external(buf, bytes);
    u52::multiply(z, a, size_t(an), b, size_t(bn), g);
}

extern "C" void sbn3f_full(limb *z, const limb *a, int64_t an, const limb *b, int64_t bn) noexcept {
    full_product(z, a, an, b, bn, nullptr);
}

namespace sbn::v3::fp {
namespace {

// Split of the short product: the top s = ceil(42 n / 64) limbs by a full product (sweep 2026-10-12,
// 38..52 / 64 at n = 300..3000: within 5%, 42 best or close everywhere).
#ifndef FPK_SH_BETA64
#define FPK_SH_BETA64 42
#endif
#ifndef FPK_SH_BASE
#define FPK_SH_BASE 234
#endif
constexpr size_t sh_base = FPK_SH_BASE;   // the recursion's base: u52::mulhigh (at most 234)
constexpr size_t sh_split(size_t n) noexcept { return (FPK_SH_BETA64 * n + 63) / 64; }

// The high short product (Mulders; the recursion of MPFR's mpfr_mulhigh_n): rp has 2n limbs; on
// return rp[n-1 .. 2n) approximates A B / B^(n-1) from below, |error| < E(n) units of rp[n], where
// A = ap[0..n), B = bp[0..n) (ap == bp: a square). Base n <= sh_base: u52::mulhigh's n words
// (0 <= floor(AB / B^n) - r <= 1) and a zero rp[n-1]: E < 3. Otherwise, with s = sh_split(n), l = n - s:
//   AB = A1 B1 B^2l + (A1 B0 + A0 B1) B^l + A0 B0     (A1, B1 the top s limbs, A0, B0 the low l)
// A1 B1 exact into rp[2l..2n). A1 B0's limbs from l (position n) are those of A1's top l limbs times B0
// (position k = s) up to A1's low s - l limbs times B0 (< B^s at position l: < 1 unit of rp[n]); the
// recursive short product of those l x l limbs is added at rp[n-1] (its own rp[l-1 .. 2l)); the same
// for A0 B1. A0 B0 < B^2l <= B^(n-1). Hence E(n) <= 2 E(l) + 3; every part is non-negative, so the sum
// stays below B^2n (no carry out). rp[0..2l) is the recursive calls' area, disjoint from rp[n-1..).
void short_high(limb *rp, const limb *ap, const limb *bp, size_t n, Frame &f) noexcept {
    if (n <= sh_base) {
        u52::mulhigh(rp + n, ap, bp, n, f);
        rp[n - 1] = 0;
        return;
    }
    const size_t s = sh_split(n), l = n - s;
    u52::multiply(rp + 2 * l, ap + l, s, bp + l, s, f);
    short_high(rp, ap + s, bp, l, f);
    uint64_t cy = sbn3i_add_n(rp + n - 1, rp + n - 1, rp + l - 1, long(l + 1));
    if (ap == bp) cy += sbn3i_add_n(rp + n - 1, rp + n - 1, rp + l - 1, long(l + 1));   // A1 B0 = A0 B1
    else {
        short_high(rp, ap, bp + s, l, f);
        cy += sbn3i_add_n(rp + n - 1, rp + n - 1, rp + l - 1, long(l + 1));
    }
    for (limb *q = rp + n + l; cy; ++q) { *q += cy; cy = *q < cy; }
}

// Frame bytes of short_high(n): the top level's full product, then (released) the deepest base
size_t short_high_bytes(size_t n) noexcept {
    if (n <= sh_base) return u52::mulhigh_scratch_bytes(n) + 64;
    const size_t s = sh_split(n), t = u52::scratch_bytes(s, s) + 64, r = short_high_bytes(n - s);
    return t > r ? t : r;
}

// the top m limbs of x (n limbs) as an m-limb window: the limbs themselves when x has them, else a
// copy into w with zeros below
const limb *top_window(const limb *x, int64_t n, int64_t m, limb *w) noexcept {
    if (n >= m) return x + (n - m);
    for (int64_t i = 0; i < m - n; ++i) w[i] = 0;
    for (int64_t i = 0; i < n; ++i) w[m - n + i] = x[i];
    return w;
}

} // namespace

// High-product shape: the top k + 1 limbs of each operand (zero-extended when shorter), their short
// product (n = k + 1) in z[0..2k+2), its top k + 1 limbs moved down: AB / B^(k-1) at grid L2 - 1, the
// truncations < 1/B unit each (one limb more than k), the short product < E(k+1) + 1 units of
// position k - 1: all together far below one unit of 2^(64 L2). Full shape: the windows' product.
need mul_m_need(const fx &a, const fx &b, int64_t leps) noexcept {
    const mulshape s = mul_shape(a, b, leps);
    if (s.k <= 0) return {0, 0};
    if (s.full) return {s.ka + s.kb, u52::scratch_bytes(size_t(s.ka), size_t(s.kb)) + 64};
    const size_t n = size_t(s.k) + 1;
    return {int64_t(2 * n), 2 * (8 * n + 64) + short_high_bytes(n)};
}

static fxr product_m(limb *z, const fx &a, const fx &b, int64_t leps, Frame &f) noexcept {
    const mulshape s = mul_shape(a, b, leps);
    if (s.k <= 0) return {0, 0};
    int64_t n, e = a.e + b.e;
    if (s.full) {
        full_product(z, a.d + (len(a.ns) - s.ka), s.ka, b.d + (len(b.ns) - s.kb), s.kb, &f);
        n = s.ka + s.kb;
    } else {
        FrameMark mark(f);
        n = s.k + 1;
        const limb *aw = top_window(a.d, len(a.ns), n, f.alloc<limb>(size_t(n)));
        const limb *bw = &b == &a ? aw : top_window(b.d, len(b.ns), n, f.alloc<limb>(size_t(n)));
        short_high(z, aw, bw, size_t(n), f);
        for (int64_t i = 0; i < n; ++i) z[i] = z[n + i];
    }
    while (n && z[n - 1] == 0) --n, --e;
    if (!n) return {0, 0};
    return {e, uint64_t(n) | ((a.ns ^ b.ns) & sign_bit)};
}

fxr mul_m(limb *z, const fx &a, const fx &b, int64_t leps, Frame &f) noexcept { return product_m(z, a, b, leps, f); }
fxr sqr_m(limb *z, const fx &a, int64_t leps, Frame &f) noexcept { return product_m(z, a, a, leps, f); }

} // namespace sbn::v3::fp
